324:     /// Records a peer's reference to a message, acquiring an `Arc` only when
325:     /// the cache needs to store the message.
326:     fn insert_cache_entry(
327:         &mut self,
328:         peer: P,
329:         digest: M::Digest,
330:         make_shared: impl FnOnce() -> Arc<M>,
331:     ) -> InsertMessageResult {
332:         // Only peers listed in `latest.primary` may buffer
333:         if self.latest_primary_peers.position(&peer).is_none() {
334:             return InsertMessageResult::Ineligible;
335:         }
336: 
337:         // Get the relevant deque for the peer
338:         let deque = self
339:             .deques
340:             .entry(peer)
341:             .or_insert_with(|| VecDeque::with_capacity(self.deque_size + 1));
342: 
343:         // If the message is already in the deque, move it to the front and return early
344:         if let Some(i) = deque.iter().position(|d| *d == digest) {
345:             if i != 0 {
346:                 let v = deque.remove(i).unwrap(); // Must exist
347:                 deque.push_front(v);
348:             }
349:             return InsertMessageResult::Duplicate;
350:         };
351: 
352:         // - Insert the digest into the peer cache
353:         // - Increment the item count
354:         // - Insert the message if-and-only-if the new item count is 1
355:         deque.push_front(digest);
356:         let count = self
357:             .counts
358:             .entry(digest)
359:             .and_modify(|c| *c = c.checked_add(1).unwrap())
360:             .or_insert(1);
361:         if *count == 1 {
362:             let existing = self.items.insert(digest, make_shared());
363:             assert!(existing.is_none());
364:         }
