367:         if deque.len() > self.deque_size {
368:             // Remove the oldest item from the peer cache
369:             // Decrement the item count
370:             // Remove the message if-and-only-if the new item count is 0
371:             let stale = deque.pop_back().unwrap();
372:             decrement_digest_refcount(&mut self.counts, &mut self.items, &stale);
373:         }
